package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Stack;
import java.util.Random;

public class OnlineStockSpanTest {

    @Test
    public void next_0() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertEquals(1, solution.next(0));
    }

    @Test
    public void next_NegativeNumber() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertEquals(1, solution.next(-100));
    }

    @Test
    public void calculateSpans_EmptyArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[0]);
        assertTrue(result.length == 0);
    }

    @Test
    public void calculateSpans_SingleElementArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {100};
        int[] result = solution.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void next_0Again() {
        OnlineStockSpan solution = new OnlineStockSpan();
        solution.next(0);
        assertEquals(2, solution.next(0));
    }

    @Test
    public void next_DifferentPriceThenZero() {
        OnlineStockSpan solution = new OnlineStockSpan();
        solution.next(50);
        assertEquals(1, solution.next(100));
    }

    @Test
    public void calculateSpans_SimpleSequence() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        int[] result = solution.calculateSpans(prices);
        assertTrue(result.length == 3);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
    }

    @Test
    public void calculateSpans_IncreasingSequence() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {10, 20, 30, 40};
        int[] result = solution.calculateSpans(prices);
        assertTrue(result.length == 4);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
        assertEquals(4, result[3]);
    }

    @Test
    public void calculateSpans_DecreasingSequence() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {40, 30, 20};
        int[] result = solution.calculateSpans(prices);
        assertTrue(result.length == 3);
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
    }

    @Test
    public void next_ConsecutiveNumbers() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        for (int price : prices) {
            solution.next(price);
        }
        assertEquals(1, solution.next(100));
    }

    @Test
    public void calculateSpans_ConsecutiveNumbers() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        int[] result = solution.calculateSpans(prices);
        for (int i = 0; i < result.length; i++) {
            assertEquals(i + 1, result[i]);
        }
    }

    @Test
    public void next_NegativeNumbers() {
        OnlineStockSpan solution = new OnlineStockSpan();
        Random random = new Random(1234);
        for (int i = 0; i < 10000; i++) {
            int price = -random.nextInt(50) + 10;
            solution.next(price);
        }
    }

    @Test
    public void calculateSpans_NegativeNumbers() {
        OnlineStockSpan solution = new OnlineStockSpan();
        Random random = new Random(1234);
        for (int i = 0; i < 10000; i++) {
            int price = -random.nextInt(50) + 10;
            int[] result = solution.calculateSpans(new int[]{price});
            assertEquals(1, result[0]);
    }

    @Test
    public void next_ZeroConsecutive() {
        OnlineStockSpan solution = new OnlineStockSpan();
        for (int i = 0; i < 10000; i++) {
            solution.next(0);
        }
        solution.next(-10);
        assertEquals(1, solution.next(0));
    }

    @Test
    public void calculateSpans_ZeroConsecutive() {
        OnlineStockSpan solution = new OnlineStockSpan();
        for (int i = 0; i < 10000; i++) {
            int price = -i;
            solution.next(price);
        }
        int[] result = solution.calculateSpans(new int[]{10});
        assertEquals(1, result[0]);
    }

}

